INSERT INTO `posts` VALUES (1,'赤坎老街的灵魂蘸料：姜蓉白切鸡','今天跑过大马路，三十年老店的姜蓉简直绝了，鸡肉皮爽肉嫩，加上秘制蘸料，一口封神...','https://images.unsplash.com/photo-1626074353765-517a681e40be',NULL,'赤坎区',1200,86,'2026-04-28 03:47:07',1,NULL,NULL,0),(2,'赤坎老街的港式生滚肠粉','三十年老店的姜蓉简直绝了，鸡肉皮爽肉嫩。还得看淡淡的米香，加上秘制蘸料，一口封神...','https://images.unsplash.com/photo-1563379091339-03b21ab4a4f8?auto=format&fit=crop&w=400&q=80',NULL,'赤坎区',952,64,'2026-04-28 03:47:07',1,NULL,NULL,0),(3,'赤坎老街的灵魂：花生白切','鸡肉皮爽肉嫩，加上秘制蘸料，一口封神。根本停不下来！','https://images.unsplash.com/photo-1512621776951-a57141f2eefd',NULL,'赤坎区',732,45,'2026-04-28 03:47:07',1,NULL,NULL,0),(4,'湛江糖水地图 | 这5家让我无限回购','炎热的夏天，怎能少了一碗清凉的糖水呢？整理了我心中的湛江糖水Top5，好吃不踩雷！','https://images.unsplash.com/photo-1497034825429-c343d7c6a68f',NULL,NULL,0,0,'2026-05-02 07:34:13',1,NULL,NULL,0),(101,'官渡生蚝：海味里的白月光','官渡的生蚝以鲜嫩肥美著称，不需繁琐调味，原汁原味最动人...','https://pic.imgdb.cn/item/662f4e0c0ea3701da3b3f46a.jpg',NULL,NULL,0,0,'2026-04-29 08:23:24',1,NULL,NULL,0),(102,'赤坎老街的生粉，是湛江人的清晨慰藉','这家开了三十年的老店，皮薄如纸，每一口都是米浆的清香...','https://pic.imgdb.cn/item/662f4e3b0ea3701da3b48202.jpg',NULL,NULL,0,0,'2026-04-29 08:23:24',1,NULL,NULL,0),(103,'躲在小巷里的牛杂煲，汤底是灵魂','只有本地人才找得到的宝藏店铺，牛杂软烂入味，萝卜吸饱了汤汁...','https://pic.imgdb.cn/item/662f4e720ea3701da3b5264b.jpg',NULL,NULL,0,0,'2026-04-29 08:23:24',1,NULL,NULL,0),(104,'赤坎老街的港式生滚肠粉','这里是详细的正文内容...','https://your-storage.com/changfen.jpg',NULL,'赤坎区',952,64,'2026-05-06 01:14:09',1,'三十年老店的姜蓉简直绝了...','探店',1),(105,'湛江糖水地图 | 这5家让我无限回购','这里是详细的正文内容...','https://your-storage.com/tongshui.jpg',NULL,'霞山区',512,35,'2026-05-06 01:14:17',1,'炎热的夏天，怎能少了一碗清凉的糖水呢？','攻略',0),(108,'123','www','/upload/f7c7d258-f9e8-40c9-b08b-15911850f5f9.webp','[\"/upload/f96cf51c-749e-40ba-9008-82ccd6552096.webp\"]','赤坎区',0,0,'2026-05-09 22:05:19',20260001,'www','探店',0),(109,'极品探店91蒋先生力推门店，双区兄弟吃到无法自拔','回笼叉烧饭搭配极品白切鸡，叉烧饭用极品笼子加火熬制7天7夜，再用幌金绳吊起晒足9178天，用扇子煽动8级大火烧制而成，而白切鸡采用精品走地鸡，用紫金葫芦收集精油浇给，美味十足，令人无法自拔。','/upload/11de9477-5176-40c9-be38-0617d9ab88c4.jpg','[\"/upload/aa47f7f7-d028-443b-81d8-2c5551590fda.jpg\", \"/upload/ad5b49c8-993d-4335-815b-f446362841c1.jpg\", \"/upload/66448b5e-c3db-4ea1-bf5a-a65729f4af24.jpg\"]','吴川市',0,0,'2026-05-11 00:49:53',20260001,'回笼叉烧饭搭配极品白切鸡，叉烧饭用极品笼子加火熬制7天7夜，再用幌金绳吊起晒足9178天，用扇子煽动8级大火烧制而成，而白切鸡采用精品走地鸡，用紫金葫芦收集精油浇给，美味十足，令人无法自拔。','探店',0);
