INSERT INTO `talk_ranking` VALUES (1,'林小厨','湛江的白切鸡真的是一绝，皮爽肉滑！','/Image/Talk1.png',5,'2026-04-20 13:17:47'),(2,'美食家阿强','赤坎老街那家牛腩粉，味道还是没变。','/Image/Talk2.png',3,'2026-04-20 13:21:15'),(3,'逛吃湛江','生蚝非常肥美，蒜蓉配比刚刚好。','/Image/Talk3.png',4,'2026-04-20 13:21:15'),(4,'粤西食客','好吃，爱吃','/Image/Talk4.png',5,'2026-04-20 13:21:15');
