--
-- Table structure for table `taste_card`
--

DROP TABLE IF EXISTS `taste_card`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `taste_card` (
  `id` varchar(10) NOT NULL,
  `name` varchar(255) NOT NULL,
  `en_name` varchar(100) DEFAULT NULL,
  `desc` text,
  `bg_color` varchar(7) DEFAULT NULL,
  `image_path` varchar(255) DEFAULT '/images/food/default.png',
  `tags` json DEFAULT NULL,
  `origin` varchar(100) DEFAULT NULL,
  `season` varchar(100) DEFAULT NULL,
  `main_methods` varchar(255) DEFAULT NULL,
  `taste_profile` varchar(255) DEFAULT NULL,
  `features` json DEFAULT NULL,
  `nutrition` json DEFAULT NULL,
  `culture` json DEFAULT NULL,
  `recipes` json DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

