LOCK TABLES `taste_card` WRITE;
/*!40000 ALTER TABLE `taste_card` DISABLE KEYS */;
INSERT INTO `taste_card` VALUES ('01','官渡生蚝','Oyster','嫩滑鲜甜，碳烤绝佳。','#A8A196','/images/food/01.png','[\"湛江海鲜代表\", \"高蛋白\", \"鲜美浓郁\", \"时令美味\"]','湛江市官渡镇','每年 10 月 - 次年 4 月','生蚝 / 蒜蓉烤生蚝 / 椒盐生蚝 / 生蚝粥','鲜甜多汁，蚝香浓郁','{\"text\": \"个头大，壳厚实，蚝肉肥美饱满，色泽乳白透亮，入口鲜甜，回味带有淡淡的海水咸香。\", \"keywords\": [\"壳厚坚硬\", \"蚝肉饱满\", \"鲜甜无腥\"]}','{\"text\": \"生蚝富含优质蛋白、锌、铁、钙等多种矿物质，营养丰富，有助于增强免疫力和体力。\", \"keywords\": [\"高蛋白\", \"含锌丰富\", \"低脂肪\", \"多种矿物质\"]}','{\"list\": [\"海边传统美食，历史悠久\", \"家常烹饪，做法多样\", \"生蚝节是当地重要民俗活动\", \"象征鲜美与丰收\"], \"text\": \"在湛江，生蚝不仅是餐桌上的美味，更是海边人生活的一部分。生蚝季节，家家户户烹制生蚝，鲜美热闹。\"}','[{\"desc\": \"最原汁原味的做法，蘸上酱油芥末，鲜甜爽滑。\", \"name\": \"生蚝\"}, {\"desc\": \"蒜香浓郁，蚝肉鲜嫩，是夜市最受欢迎的做法。\", \"name\": \"蒜蓉烤生蚝\"}, {\"desc\": \"外酥里嫩，椒盐香气与蚝肉鲜味完美结合。\", \"name\": \"椒盐生蚝\"}, {\"desc\": \"蚝肉熬入粥，鲜甜暖胃，营养丰富。\", \"name\": \"生蚝粥\"}]'),('02','徐闻菠萝','Pineapple','口感清脆，独特美味。','#F5E6CC','/images/food/02.png','[\"热带水果\", \"高维C\", \"酸甜可口\", \"果香浓郁\"]','湛江市徐闻县','每年 3 月 - 5 月','生食 / 菠萝咕噜肉 / 菠萝饭 / 菠萝汁','酸甜多汁，清脆爽口','{\"text\": \"果肉金黄，汁水充沛，得益于火山红土的滋养，徐闻菠萝拥有完美的酸甜比例，入口清脆。\", \"keywords\": [\"果肉金黄\", \"汁水饱满\", \"清脆香甜\"]}','{\"text\": \"富含维生素C、菠萝蛋白酶和大量膳食纤维，有助于促进消化，清热解渴。\", \"keywords\": [\"高维生素C\", \"助消化\", \"膳食纤维\"]}','{\"list\": [\"中国菠萝之乡\", \"壮丽火山红土文化\", \"果香飘荡的生态景观\", \"甜蜜生活的代名词\"], \"text\": \"徐闻被称为“中国菠萝之乡”，拥有壮观的“菠萝的海”红土景观，不仅是丰收的象征，更是湛江的一张生态名片。\"}','[{\"desc\": \"盐水浸泡后直接食用，最能品尝到原汁原味的清甜。\", \"name\": \"鲜切生食\"}, {\"desc\": \"果香酸甜与酥脆肉块完美融合，经典粤菜风味。\", \"name\": \"菠萝咕噜肉\"}, {\"desc\": \"将鲜甜菠萝化作天然盛器，米饭浸润果香，层次丰富。\", \"name\": \"泰式菠萝饭\"}]'),('03','湛江沙虫','Sand Worm','脆嫩鲜美，名扬天下。','#D9D1C5','/images/food/03.png','[\"天然海鲜\", \"高营养\", \"鲜美无比\", \"高档食材\"]','湛江市遂溪县/雷州市沿海','每年 5 月 - 9 月','沙虫汤 / 蒜蓉蒸沙虫 / 酥炸沙虫 / 沙虫粥','极度鲜美，爽脆弹牙','{\"text\": \"对生长水质要求极高，肉质极其脆嫩鲜美，经过精心清理后白净透亮，自带纯天然的清甜。\", \"keywords\": [\"脆嫩弹牙\", \"极度鲜美\", \"纯净无沙\"]}','{\"text\": \"富含多种氨基酸、微量元素和高蛋白质，具有极高的滋补价值，被誉为海里的天然人参。\", \"keywords\": [\"高氨基酸\", \"滋阴降火\", \"低脂高蛋\"]}','{\"list\": [\"宴席顶级佳肴\", \"高端海鲜代表\", \"生态水质的晴雨表\", \"自带纯天然甘甜\"], \"text\": \"湛江沙虫是当地高规格宴席上不可或缺的顶级佳肴，素有“天然味精”的美誉，代表了湛江海鲜的极致追求。\"}','[{\"desc\": \"最能保留沙虫原汁原鲜的做法，汤汁乳白，鲜美无比。\", \"name\": \"清宣沙虫汤\"}, {\"desc\": \"蒜香逼出沙虫的鲜甜，爽脆的肉质与粉丝相得益。\", \"name\": \"蒜蓉粉丝蒸\"}, {\"desc\": \"外表金黄酥脆，内里依然保留了一丝脆嫩与海味。\", \"name\": \"酥炸沙虫\"}]'),('04','白切鸡','White Cut Chicken','皮脆肉嫩，原汁原味。','#EAE7E2','/images/food/04.png','[\"传统粤菜\", \"地道湛江味\", \"皮脆肉嫩\", \"经典招牌\"]','湛江市各县区老店','全年皆宜','白切 / 斩件搭配特制沙姜酱油','原汁原味，鸡肉鲜嫩，沙姜浓郁','{\"text\": \"选用本地优质走地三黄鸡，皮黄骨绿，肉质紧实。烹饪手法讲究“七上八下”，骨髓带微红，锁住最嫩汁水。\", \"keywords\": [\"皮脆肉嫩\", \"肉质紧实\", \"原汁原味\"]}','{\"text\": \"优质的动物蛋白质来源，不饱和脂肪酸丰富，肉质易于人体消化吸收，滋补强身。\", \"keywords\": [\"优质蛋白\", \"易于吸收\", \"能量充沛\"]}','{\"list\": [\"无鸡不成宴\", \"广东名鸡之首\", \"灵魂沙姜酱油\", \"市井烟火的代表\"], \"text\": \"湛江人“无鸡不成宴”，湛江白切鸡位列广东名鸡之首。而独特的本地“沙姜酱油”，则是这道菜的灵魂伴侣。\"}','[{\"desc\": \"皮脆肉嫩，蘸上本地特有的沙姜花生油酱油，绝配。\", \"name\": \"经典白切鸡\"}, {\"desc\": \"浸润了鸡油的米饭香气扑鼻，搭配几块嫩鸡，极为满足。\", \"name\": \"白切鸡铺米饭\"}]'),('05','本地海鲜','Local Seafood','鲜美无比，大海馈赠。','#B8CBD0','/images/food/05.png','[\"海鲜荟萃\", \"现捞现煮\", \"种类丰富\", \"极致鲜美\"]','湛江市各大海鲜码头','开海季（8月至次年5月）最为肥美','清蒸 / 白灼 / 椒盐 / 姜葱爆炒','纯粹海味，咸鲜多汁','{\"text\": \"涵盖花蟹、花虾、各类野生海鱼。湛江得天独厚的海洋环境，让这里的海鲜不需要过多调料，纯凭新鲜度取胜。\", \"keywords\": [\"现捞现做\", \"种类繁多\", \"极致新鲜\"]}','{\"text\": \"富含极高的不饱和脂肪酸、优质蛋白质及丰富的碘、锌等海洋微量元素，极为健康。\", \"keywords\": [\"高蛋白质\", \"低饱和脂肪\", \"海洋微量元素\"]}','{\"list\": [\"海鲜美食之都\", \"大排档市井文化\", \"大海的纯真馈赠\", \"现捞现煮的极致\"], \"text\": \"作为“中国海鲜美食之都”，在排档吃一顿刚上岸的本地海鲜，是每一个湛江人乃至外地游客最核心的生活仪式。\"}','[{\"desc\": \"最简单的烹饪方式，保留虾肉最原始的鲜甜与弹牙。\", \"name\": \"白灼基围虾\"}, {\"desc\": \"姜葱的辛香完美融入蟹肉中，肉质饱满，鲜香四溢。\", \"name\": \"姜葱炒花蟹\"}, {\"desc\": \"火候恰到好处，鱼肉呈蒜瓣状，淋上蒸鱼豉油即可。\", \"name\": \"清蒸海捕鱼\"}]'),('06','雷州番薯','Sweet Potato','甜糯可口，回味无穷。','#7D634B','/images/food/06.png','[\"地道粗粮\", \"高膳食纤维\", \"甜糯可口\", \"红土种植\"]','湛江雷州市','每年冬季至次年春季','柴火烤番薯 / 蒸番薯 / 番薯糖水','甜糯细腻，浓郁薯香','{\"text\": \"得益于雷州半岛独特的火山红土地质，番薯在这里积累了极高的糖分。煮熟后内芯红润，口感细腻无筋，甜度极高。\", \"keywords\": [\"红土培育\", \"口感细腻\", \"无筋甜糯\"]}','{\"text\": \"含有极为丰富的膳理纤维、胡萝卜素和多种维生素，热量适中，是有助于肠胃健康的天然粗粮。\", \"keywords\": [\"富含胡萝卜素\", \"膳食纤维\", \"排毒养颜\"]}','{\"list\": [\"半岛红土馈赠\", \"历史悠久的作物\", \"现代健康粗粮\", \"纯朴的乡村味道\"], \"text\": \"雷州番薯曾在历史干旱时期救活无数百姓，如今这道曾经的“救荒粮”，早已蜕变为都市人追求健康养生的地道美味。\"}','[{\"desc\": \"烤到流糖油的番薯，薯皮微焦，内芯甜糯，香气扑鼻。\", \"name\": \"柴火烤番薯\"}, {\"desc\": \"番薯切块，加入老姜和红糖慢熬，甜润暖胃，非常经典。\", \"name\": \"雷州番薯糖水\"}]'),('07','廉江红橙','Red Orange','汁多味浓，果香诱人。','#E9C6B0','/images/food/07.png','[\"国家地理标志\", \"皮薄汁多\", \"酸甜适度\", \"果肉红润\"]','湛江廉江市','每年 11 月 - 次年 1 月','鲜食 / 榨汁','浓郁多汁，酸甜可口','{\"text\": \"果肉橙红甚至微红，皮薄肉厚。汁水极多，化渣率极高，几乎没有果肉的粗糙感，有一种独特的浓郁果香。\", \"keywords\": [\"皮薄肉厚\", \"化渣率高\", \"果红汁多\"]}','{\"text\": \"富含大量的维生素C、柠檬酸、葡萄糖和丰富水分，具有很好的生津止渴、清热润肺功效。\", \"keywords\": [\"清热润肺\", \"生津止渴\", \"维C之王\"]}','{\"list\": [\"中国红橙之乡\", \"曾入选国宴佳果\", \"地理标志保护产品\", \"冬季甜蜜的期盼\"], \"text\": \"廉江被誉为“中国红橙之乡”，因其品质极佳，曾被选为国宴佳果招待外宾，是湛江水果界的骄傲。\"}','[{\"desc\": \"剥皮即食，饱满的果肉在口中爆开，感受最纯粹的酸甜。\", \"name\": \"直接鲜食\"}, {\"desc\": \"纯手工或机器榨取，不加一滴水和糖，纯天然的果汁享受。\", \"name\": \"鲜榨红橙汁\"}]'),('08','霞山鱼丸','Fish Ball','弹牙入味，鲜而不腻。','#D4D6D1','/images/food/08.png','[\"手工制作\", \"弹牙爽脆\", \"老街味道\", \"鲜美汤品\"]','湛江市霞山区老街','全年皆宜','清汤煮 / 火锅煮 / 咖喱鱼丸','鲜美弹牙，清爽不腻','{\"text\": \"精选新鲜海鱼（如九棍鱼或那哥鱼）肉，纯手工用木棒捶打上劲。不添加任何防腐剂，煮熟后口感极具弹性，咬下去还会爆汁。\", \"keywords\": [\"纯手工捶打\", \"真鱼肉制作\", \"劲道爆汁\"]}','{\"text\": \"鱼肉纯度极高，属于高蛋白、低脂肪、低热量的健康食品，适合各年龄段人群食用。\", \"keywords\": [\"高蛋白质\", \"低脂低热\", \"天然无添加\"]}','{\"list\": [\"老街非遗味道\", \"几代人的街头记忆\", \"市井早茶与宵夜\", \"纯粹的手工匠心\"], \"text\": \"霞山老街里的手打鱼丸档口，承载了几代湛江人的街头记忆。一碗热气腾腾的清汤鱼丸，就是最地道的湛江早茶或宵夜。\"}','[{\"desc\": \"搭配几片生菜或芹菜粒，清汤中煮熟，汤清鱼丸鲜，极具弹性。\", \"name\": \"老街清汤鱼丸\"}, {\"desc\": \"浓郁的咖喱酱汁包裹着爽脆的鱼丸，别有一番街头风味。\", \"name\": \"咖喱手打鱼丸\"}]'),('09','湛江泥丁','Sea Slug','口感独特，鲜灵爽口。','#E2DACE','/images/food/09.png','[\"滩涂珍宝\", \"爽脆无比\", \"小众美味\", \"下酒好菜\"]','湛江沿海滩涂泥沙中','每年春夏季节','土榨花生油凉拌 / 泥丁粥 / 爆炒泥丁','爽脆清甜，富有嚼劲','{\"text\": \"生长在纯净的滩涂中，形似小香肠。虽然外表朴素，但清洗干净后焯水，口感极其爽脆，且自带一种海水泥沙孕育出的独特清甜。\", \"keywords\": [\"滩涂奇珍\", \"极致爽脆\", \"清甜有嚼劲\"]}','{\"text\": \"虽然体型小，但营养价值极高，富含蛋白质和多种人体必需的氨基酸，具有滋阴补肾的功效。\", \"keywords\": [\"滋补强身\", \"高氨基酸\", \"海洋野味\"]}','{\"list\": [\"赶海文化代表\", \"本地人私藏美味\", \"滩涂上的黑珍珠\", \"极致的爽脆口感\"], \"text\": \"泥丁是湛江赶海文化（本地俗称“下海赶滩”）的经典收获。外地人或许不敢轻易尝试，但在本地人眼中，它是绝对的极品珍馐。\"}','[{\"desc\": \"焯水后的泥丁，淋上湛江本地纯正土榨花生油和酱油，爽脆到极致。\", \"name\": \"花生油凉拌泥丁\"}, {\"desc\": \"将泥丁放入绵密的白粥中同煮，白粥完全吸收了泥丁的鲜甜，暖胃无比。\", \"name\": \"鲜美泥丁粥\"}]'),('10','坡头大闸蟹','Hairy Crab','黄满膏肥，季节限定。','#C5B199','/images/food/10.png','[\"咸淡水交汇\", \"黄满膏肥\", \"秋季限定\", \"肉质鲜甜\"]','湛江市坡头区沿海海湾','每年 9 月 - 11 月','原只清蒸 / 姜葱炒大闸蟹 / 蟹肉粥','膏腴浓郁，蟹肉鲜甜','{\"text\": \"生长在江海交汇的咸淡水域，这里的蟹壳坚硬，肉质比纯淡水蟹多了一丝天然的咸鲜。打开后满是金黄肥美的蟹膏，肉质洁白如丝。\", \"keywords\": [\"黄满膏肥\", \"咸淡水交融\", \"秋季限定\"]}','{\"text\": \"富含优质蛋白质、钙、磷、铁及多种维生素，尤其是蟹黄中含有丰富的微量元素，滋补美味。\", \"keywords\": [\"富含蛋白质\", \"高钙滋补\", \"秋季营养\"]}','{\"list\": [\"秋季限定盛宴\", \"江海交汇的异禀\", \"老饕的驱车追寻\", \"唇齿留香的膏腴\"], \"text\": \"秋风起，蟹脚痒。坡头吃蟹是湛江秋季的一大盛事。每逢时节，市区的食客便会专程驱车前往坡头，只为追逐这口限定的丰腴。\"}','[{\"desc\": \"反扣上锅清蒸，最大程度保留蟹黄的完整与蟹肉的鲜甜，原汁原味。\", \"name\": \"原只清蒸大闸蟹\"}, {\"desc\": \"将蟹斩件，大火爆炒，姜葱的辛辣完美勾勒出蟹壳中残留的海味。\", \"name\": \"姜葱炒大闸蟹\"}]'),('11','湛江烧鹅','Roasted Goose','皮脆肉香，油脂丰盈。','#D9C5B2','/images/food/11.png','[\"传统烧腊\", \"皮脆肉嫩\", \"油脂丰盈\", \"醇厚浓郁\"]','湛江市各大传统烧腊老店','全年皆宜','明炉挂烤 / 搭配原汁卤水或酸梅酱','皮脆多汁，甘香浓郁','{\"text\": \"选用本地肥美的乌鬃鹅，用秘制酱料填入鹅腹并缝合，经过吹气、上皮水、风干后放入明炉烘烤。出炉时皮脆如纸，油脂丰盈，肉汁紧锁。\", \"keywords\": [\"明炉挂烤\", \"脆皮多汁\", \"油脂甘香\"]}','{\"text\": \"鹅肉中富含不饱和脂肪酸和优质蛋白质，不饱和脂肪酸含量高，对心血管相对友好，能量充沛。\", \"keywords\": [\"不饱和脂肪酸\", \"优质蛋白质\", \"丰盈御寒\"]}','{\"list\": [\"市井斩料文化\", \"档口灵魂支柱\", \"皮色红润的诱惑\", \"市井生活的幸福感\"], \"text\": \"街头巷尾的烧腊档是湛江市井生活的灵魂之一。每逢佳节或家庭聚会，“斩边烧鹅”回家加餐，就是最接地气也最高规格的幸福。\"}','[{\"desc\": \"刚出炉的烧鹅斩件，淋上烤鹅时流出的原汁原酱，丰腴甘香。\", \"name\": \"极品明炉烧鹅\"}, {\"desc\": \"将烧鹅铺在爽滑的濑粉上，浓郁的鹅油融入清汤中，每一口粉都裹满香气。\", \"name\": \"招牌烧鹅濑粉\"}]'),('12','湛江虾饼','Shrimp Cake','香脆鲜甜，街头至味。','#E6CCB2','/images/food/12.png','[\"非遗街头小吃\", \"金黄酥脆\", \"鲜虾满布\", \"童年回忆\"]','湛江市赤坎老街/历史街区','全年皆宜','油炸（现炸现卖）','酥脆香浓，鲜甜可口','{\"text\": \"在一把特制的浅平铁勺上铺上稀面糊，大方地撒上几只带壳的新鲜海虾，迅速下入滚油中炸至金黄。虾壳香脆，面饼酥软，虾肉鲜甜。\", \"keywords\": [\"现炸金黄\", \"带壳鲜虾\", \"外酥里嫩\"]}','{\"text\": \"因为保留了完整的鲜虾外壳，炸酥后可以直接食用，提供了丰富的钙质、蛋白质和甲壳素。\", \"keywords\": [\"富含天然钙质\", \"高优质蛋白\", \"香脆易吸收\"]}','{\"list\": [\"老街非遗记忆\", \"隐秘的角落符号\", \"街头摊位烟火气\", \"童年的那口酥脆\"], \"text\": \"赤坎老街最富盛名的民间小吃，承载了无数湛江人的童年记忆。随着影视剧《隐秘的角落》在此取景，这道街头至味也成为了全国游客打卡的符号。\"}','[{\"desc\": \"刚从油锅捞出略微沥油，烫手时咬下，虾壳爆裂，香气混着热气直冲鼻腔。\", \"name\": \"经典现炸虾饼\"}]');
